css:
.container {
  width: 100%;
  height: 100%;
  position: relative;
  background: #f0f0f0;
}

.container::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
      45deg,
      #6ab5b9 25%,
      transparent 25%,
      transparent 50%,
      #6ab5b9 50%,
      #6ab5b9 75%,
      transparent 75%,
      transparent
    ),
    linear-gradient(
      -45deg,
      #6ab5b9 25%,
      transparent 25%,
      transparent 50%,
      #6ab5b9 50%,
      #6ab5b9 75%,
      transparent 75%,
      transparent
    );
  background-size: 20px 20px;
  opacity: 0.8;
}
